import '../../../src/quill.js';
import { describe, expect, test, vi, beforeEach, afterEach } from 'vitest';
import Quill, { expandConfig } from '../../../src/core/quill.js';
import createRegistryWithFormats from '../../../src/core/utils/createRegistryWithFormats.js';
import * as Parchment from 'parchment';

const testContainerId = 'testContainer2';

const createContainer = () => {
  const container = document.createElement('div');
  container.id = testContainerId;
  document.body.appendChild(container);
  return container;
};

describe('formats option', () => {
  beforeEach(() => {
    createContainer();
  });

  afterEach(() => {
    const el = document.getElementById(testContainerId);
    if (el) el.remove();
  });

  test('when formats is null, global registry is used', () => {
    const config = expandConfig(`#${testContainerId}`, {
      formats: null,
    });
    expect(config.registry).toBeDefined();
  });

  test('when formats is not provided, global registry is used', () => {
    const config = expandConfig(`#${testContainerId}`, {});
    expect(config.registry).toBeDefined();
  });

  test('formats array creates a registry with core blots + requested formats', () => {
    const config = expandConfig(`#${testContainerId}`, {
      formats: ['bold', 'italic'],
    });
    // Core blots should be present
    expect(config.registry.query('block', Parchment.Scope.BLOT)).toBeTruthy();
    expect(config.registry.query('break', Parchment.Scope.BLOT)).toBeTruthy();
    expect(config.registry.query('cursor', Parchment.Scope.BLOT)).toBeTruthy();
    expect(config.registry.query('inline', Parchment.Scope.BLOT)).toBeTruthy();
    expect(config.registry.query('scroll', Parchment.Scope.BLOT)).toBeTruthy();
    expect(config.registry.query('text', Parchment.Scope.BLOT)).toBeTruthy();
    // Requested formats should be present
    expect(config.registry.query('bold', Parchment.Scope.BLOT)).toBeTruthy();
    expect(config.registry.query('italic', Parchment.Scope.BLOT)).toBeTruthy();
    // Unrequested formats should NOT be present
    expect(config.registry.query('header', Parchment.Scope.BLOT)).toBeFalsy();
    expect(config.registry.query('strike', Parchment.Scope.BLOT)).toBeFalsy();
  });

  test('unknown format names are skipped without error', () => {
    const config = expandConfig(`#${testContainerId}`, {
      formats: ['bold', 'nonexistent-format'],
    });
    expect(config.registry.query('bold', Parchment.Scope.BLOT)).toBeTruthy();
    expect(config.registry.query('nonexistent-format', Parchment.Scope.BLOT)).toBeFalsy();
  });

  test('explicit registry takes precedence over formats', () => {
    const customRegistry = new Parchment.Registry();
    const config = expandConfig(`#${testContainerId}`, {
      registry: customRegistry,
      formats: ['bold'],
    });
    expect(config.registry).toBe(customRegistry);
  });
});

describe('createRegistryWithFormats', () => {
  test('returns source registry when formats is null', () => {
    const sourceRegistry = new Parchment.Registry();
    const debugLogger = { error: vi.fn() };
    const result = createRegistryWithFormats(null, sourceRegistry, debugLogger);
    expect(result).toBe(sourceRegistry);
    expect(debugLogger.error).not.toHaveBeenCalled();
  });

  test('returns source registry when formats is undefined', () => {
    const sourceRegistry = new Parchment.Registry();
    const debugLogger = { error: vi.fn() };
    const result = createRegistryWithFormats(undefined, sourceRegistry, debugLogger);
    expect(result).toBe(sourceRegistry);
    expect(debugLogger.error).not.toHaveBeenCalled();
  });

  test('registers requested format and its requiredContainer recursively', () => {
    const sourceRegistry = new Parchment.Registry();
    const debugLogger = { error: vi.fn() };

    // Register list and list-container
    const List = {
      blotName: 'list',
      tagName: 'LI',
      scope: Parchment.Scope.BLOCK,
      create: () => {
        const el = document.createElement('li');
        return el;
      },
    };
    const ListContainer = {
      blotName: 'list-container',
      tagName: 'OL',
      scope: Parchment.Scope.BLOCK,
      create: () => {
        const el = document.createElement('ol');
        return el;
      },
      allowedChildren: [],
    };
    (List as any).requiredContainer = ListContainer;

    sourceRegistry.register(List);
    sourceRegistry.register(ListContainer);

    const result = createRegistryWithFormats(['list'], sourceRegistry, debugLogger);

    expect(result.query('list', Parchment.Scope.BLOT)).toBeTruthy();
    expect(result.query('list-container', Parchment.Scope.BLOT)).toBeTruthy();
    // block is a core blot, should be present
    expect(result.query('block', Parchment.Scope.BLOT)).toBeTruthy();
  });

  test('reports unknown format names', () => {
    const sourceRegistry = new Parchment.Registry();
    const debugLogger = { error: vi.fn() };

    const result = createRegistryWithFormats(['nonexistent'], sourceRegistry, debugLogger);

    expect(debugLogger.error).toHaveBeenCalledWith(
      expect.stringContaining('nonexistent')
    );
    expect(debugLogger.error).toHaveBeenCalledWith(
      expect.stringContaining('not found')
    );
  });

  test('detects cycles in required containers', () => {
    const sourceRegistry = new Parchment.Registry();
    const debugLogger = { error: vi.fn() };

    // Create a cycle: A requires B, B requires A
    const BlotA = {
      blotName: 'cycle-a',
      tagName: 'DIV',
      scope: Parchment.Scope.BLOCK,
      create: () => document.createElement('div'),
    };
    const BlotB = {
      blotName: 'cycle-b',
      tagName: 'DIV',
      scope: Parchment.Scope.BLOCK,
      create: () => document.createElement('div'),
    };
    (BlotA as any).requiredContainer = BlotB;
    (BlotB as any).requiredContainer = BlotA;

    sourceRegistry.register(BlotA);
    sourceRegistry.register(BlotB);

    const result = createRegistryWithFormats(['cycle-a'], sourceRegistry, debugLogger);

    expect(debugLogger.error).toHaveBeenCalledWith(
      expect.stringContaining('Cycle detected')
    );
  });

  test('registers the format even when its requiredContainer has a cycle', () => {
    const sourceRegistry = new Parchment.Registry();
    const debugLogger = { error: vi.fn() };

    // A requires B, B requires A (cycle), but A itself should still be registered
    const BlotA = {
      blotName: 'cycle-a',
      tagName: 'DIV',
      scope: Parchment.Scope.BLOCK,
      create: () => document.createElement('div'),
    };
    const BlotB = {
      blotName: 'cycle-b',
      tagName: 'DIV',
      scope: Parchment.Scope.BLOCK,
      create: () => document.createElement('div'),
    };
    (BlotA as any).requiredContainer = BlotB;
    (BlotB as any).requiredContainer = BlotA;

    sourceRegistry.register(BlotA);
    sourceRegistry.register(BlotB);

    const result = createRegistryWithFormats(['cycle-a'], sourceRegistry, debugLogger);

    // The format itself should be registered before entering the cycle
    expect(result.query('cycle-a', Parchment.Scope.BLOT)).toBeTruthy();
  });
});

