  const Cursor = {
    blotName: 'cursor',
    tagName: 'SPAN',
    scope: Parchment.Scope.INLINE,
    create: () => document.createElement('span'),
  };
  const Scroll = {
    blotName: 'scroll',
    tagName: 'DIV',
    scope: Parchment.Scope.BLOCK_BLOT,
